/* domains/ai/foundations.css */
/* AI 目录卡片与 AI 工具详情视觉。 */

.vibehub-source .ai-preview {
  width: min(390px, 100%);
  display: grid;
  justify-items: center;
  gap: 10px;
  color: var(--text);
}

.vibehub-source .ai-preview > strong {
  font-size: 17px;
  font-weight: 680;
}
.vibehub-source .ai-preview > div {
  width: 100%;
  display: flex;
  align-items: stretch;
  justify-content: center;
  gap: 5px;
}
.vibehub-source .ai-preview > div span {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 6px 7px;
  border: 1px solid var(--border);
  border-radius: 7px;
  color: var(--text-2);
  background: var(--bg);
  font-size: 10px;
}
.vibehub-source .ai-preview > div span i {
  width: 16px;
  height: 16px;
  display: grid;
  place-items: center;
  flex: none;
  border-radius: 5px;
  color: var(--brand);
  background: var(--brand-light);
  font-size: 9px;
  font-style: normal;
  font-weight: 700;
}
.vibehub-source .ai-preview > div > b {
  align-self: center;
  color: var(--text-3);
  font-size: 10px;
  font-weight: 400;
}

/* Agent 与工具：从详情主图提炼出的列表缩略图，各自保留真实对象和核心关系。 */
.vibehub-source .ai-card-visual {
  width: min(420px, 100%);
  min-height: 128px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 8px;
  color: var(--text);
  font-size: 11px;
}
.vibehub-source .ai-card-visual * {
  box-sizing: border-box;
}
.vibehub-source .ai-card-visual small {
  color: var(--text-3);
  font-size: 10px;
  font-weight: 560;
  line-height: 1.25;
}
.vibehub-source .ai-card-visual b,.vibehub-source
.ai-card-visual strong {
  line-height: 1.3;
}
.vibehub-source .ai-card-visual .ok {
  color: var(--green);
}
.vibehub-source .ai-card-visual .fail {
  color: var(--red);
}
.vibehub-source .ai-card-openai-compatible-api {
  gap: 7px;
  padding: 12px 14px;
  border: 1px solid var(--border-light);
  border-radius: 8px;
  background: var(--bg-soft);
}
.vibehub-source .ai-card-openai-compatible-row {
  min-width: 0;
  min-height: 24px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 24px minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  color: var(--text-2);
  font-size: 11px;
  line-height: 1.35;
}
.vibehub-source .ai-card-openai-compatible-row > span,.vibehub-source
.ai-card-openai-compatible-row > code {
  min-width: 0;
  overflow-wrap: anywhere;
}
.vibehub-source .ai-card-openai-compatible-row > b {
  color: var(--brand);
  font-size: 14px;
  font-weight: 500;
  line-height: 1;
  text-align: center;
}
.vibehub-source .ai-card-openai-compatible-row > code {
  color: var(--brand);
  font:
    600 11px/1.35 ui-monospace,
    SFMono-Regular,
    Menlo,
    monospace;
}
.vibehub-source .aic-foot {
  min-height: 25px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 5px 8px;
  border-radius: 6px;
  background: var(--bg-soft);
  color: var(--text-2);
  font-size: 10px;
  font-style: normal;
  text-align: center;
}
.vibehub-source .aic-foot i {
  font-style: normal;
}

/* API Key：把安全存放位置与不应出现的位置放在同一张列表缩略图里。 */
.vibehub-source .ai-card-api-key {
  gap: 7px;
}
.vibehub-source .ai-card-api-key > div {
  display: grid;
  grid-template-columns: minmax(88px, 0.42fr) minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  padding: 7px 9px;
  border: 1px solid var(--border-light);
  border-radius: 7px;
  background: var(--bg);
}
.vibehub-source .ai-card-api-key > div code {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--text-2);
  font-size: 10px;
  text-align: right;
}
.vibehub-source .ai-card-api-key > div code.ok {
  color: var(--green);
}
.vibehub-source .ai-card-api-key > div code.bad {
  color: var(--red);
}

.vibehub-source .aic-goal,.vibehub-source
.aic-harness-head,.vibehub-source
.aic-skill-task,.vibehub-source
.aic-hitl-head {
  min-height: 29px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 9px;
  border: 1px solid var(--border-light);
  border-radius: 7px;
  background: var(--bg);
}
.vibehub-source .aic-goal small,.vibehub-source
.aic-harness-head small,.vibehub-source
.aic-skill-task small {
