.vibehub-source .aic-system-rule {
  border-color: color-mix(in srgb, var(--brand) 30%, var(--border));
  background: var(--brand-light);
}
.vibehub-source .aic-system-rule small {
  flex: none;
  color: var(--brand);
}
.vibehub-source .aic-system-stack {
  display: grid;
  grid-template-columns: minmax(0, 0.8fr) auto minmax(0, 1fr) auto minmax(0, 1.1fr);
  align-items: stretch;
  gap: 5px;
}
.vibehub-source .aic-system-stack > span {
  display: flex;
  min-width: 0;
  flex-direction: column;
  justify-content: center;
  gap: 3px;
  padding: 6px;
  border: 1px solid var(--border-light);
  border-radius: 7px;
  background: var(--bg);
  text-align: center;
}
.vibehub-source .aic-system-stack > span.model {
  color: var(--brand);
}
.vibehub-source .aic-system-stack > span.gate {
  border-color: color-mix(in srgb, var(--red) 28%, var(--border));
  color: var(--red);
}
.vibehub-source .aic-system-stack > i {
  align-self: center;
  color: var(--text-3);
  font-style: normal;
}

/* 无状态请求：每一轮都是独立、完整的请求包裹。 */
.vibehub-source .aic-request-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto 56px;
  align-items: center;
  gap: 7px;
}
.vibehub-source .aic-request-row section {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 3px 7px;
  padding: 7px 9px;
  border: 1px solid var(--border-light);
  border-radius: 7px;
  background: var(--bg);
}
.vibehub-source .aic-request-row section small {
  color: var(--brand);
}
.vibehub-source .aic-request-row section span {
  overflow: hidden;
  color: var(--text-3);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.vibehub-source .aic-request-row section b {
  grid-column: 1 / -1;
}
.vibehub-source .aic-request-row > i {
  color: var(--text-3);
  font-style: normal;
}
.vibehub-source .aic-request-row > .model {
  display: grid;
  height: 44px;
  place-items: center;
  border-radius: 7px;
  background: var(--brand-light);
  color: var(--brand);
  font-weight: 680;
}
.vibehub-source .aic-request-row.second section {
  border-color: color-mix(in srgb, var(--brand) 25%, var(--border));
}

/* 结构化输出：自然语言内容被约束成固定字段，再进入业务检查。 */
.vibehub-source .aic-structured-mail::before {
  content: "✉";
  color: var(--brand);
  font-size: 15px;
}
.vibehub-source .aic-structured-fields {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--brand) 24%, var(--border));
  border-radius: 8px;
  background: var(--bg);
}
.vibehub-source .aic-structured-fields span {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 4px;
  padding: 8px;
  border-right: 1px solid var(--border-light);
}
.vibehub-source .aic-structured-fields span:last-child {
  border-right: 0;
}
.vibehub-source .aic-structured-fields small {
  color: var(--brand);
  font-family: ui-monospace, monospace;
}
.vibehub-source .aic-structured-fields b {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 流式响应：离散事件持续追加成同一个仍未完成的聊天气泡。 */
.vibehub-source .aic-stream-events {
  display: flex;
  align-items: center;
  gap: 5px;
}
.vibehub-source .aic-stream-events small {
  margin-right: auto;
  color: var(--brand);
}
.vibehub-source .aic-stream-events span {
  padding: 4px 6px;
  border: 1px solid var(--border-light);
  border-radius: 5px;
  background: var(--bg);
  color: var(--text-2);
  font-size: 9px;
}
.vibehub-source .aic-stream-events > i {
  color: var(--brand);
  font-style: normal;
  letter-spacing: 2px;
}
.vibehub-source .aic-stream-bubble {
  width: min(290px, 86%);
  align-self: flex-end;
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 9px 11px;
  border-radius: 12px 12px 3px 12px;
  background: var(--brand-light);
}
.vibehub-source .aic-stream-bubble small {
  color: var(--brand);
}
.vibehub-source .aic-stream-bubble .cursor {
  display: inline-block;
  width: 2px;
  height: 12px;
  margin-left: 3px;
  vertical-align: -2px;
  background: var(--brand);
}

/* 工具调用：模型的结构化请求先过应用校验，真实执行结果再返回。 */
.vibehub-source .aic-tool-request {
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}
.vibehub-source .aic-tool-request code {
  width: 100%;
  overflow: hidden;
  color: var(--text-2);
  font-family: ui-monospace, monospace;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.vibehub-source .aic-tool-flow {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: stretch;
  gap: 7px;
}
.vibehub-source .aic-tool-flow > span {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 4px;
  padding: 7px 9px;
  border: 1px solid var(--border-light);
  border-radius: 7px;
  background: var(--bg);
}
.vibehub-source .aic-tool-flow > i {
  align-self: center;
  color: var(--text-3);
  font-style: normal;
}

/* ReAct：判断、行动、观察组成会被真实结果改写的闭环。 */
.vibehub-source .aic-react-loop {
  position: relative;
  min-height: 96px;
}
.vibehub-source .aic-react-loop > span {
  position: absolute;
  width: 42%;
  min-height: 43px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 3px;
  padding: 6px 8px;
  border: 1px solid var(--border-light);
  border-radius: 8px;
  background: var(--bg);
}
.vibehub-source .aic-react-loop .think {
  top: 0;
  left: 0;
}
.vibehub-source .aic-react-loop .act {
  top: 0;
  right: 0;
}
.vibehub-source .aic-react-loop .observe {
  right: 29%;
  bottom: 0;
}
.vibehub-source .aic-react-loop > i {
  position: absolute;
  color: var(--text-3);
  font-style: normal;
}
.vibehub-source .aic-react-loop > i.one {
  top: 15px;
  left: 48%;
}
.vibehub-source .aic-react-loop > i.two {
  top: 45px;
  right: 19%;
}
.vibehub-source .aic-react-loop > i.three {
  bottom: 8px;
  left: 23%;
}

/* Agent 循环：运行时记录轮次，并依据检查、上限和人工确认控制状态。 */
.vibehub-source .aic-loop-head {
  justify-content: space-between;
}
.vibehub-source .aic-loop-head > span {
  display: flex;
  min-width: 0;
  align-items: baseline;
  gap: 6px;
}
.vibehub-source .aic-loop-head > span small {
  color: var(--brand);
}
.vibehub-source .aic-loop-head > strong {
  flex: none;
  padding: 4px 7px;
  border-radius: 999px;
  background: var(--brand-light);
  color: var(--brand);
  font-size: 9px;
}
.vibehub-source .aic-loop-run {
  display: flex;
  align-items: center;
  gap: 5px;
}
.vibehub-source .aic-loop-run span {
  flex: 1;
  min-width: 0;
  padding: 7px 5px;
  border: 1px solid var(--border-light);
  border-radius: 6px;
  background: var(--bg);
  text-align: center;
}
.vibehub-source .aic-loop-run span.check {
  border-color: color-mix(in srgb, var(--red) 25%, var(--border));
  color: var(--red);
}
.vibehub-source .aic-loop-run i {
  color: var(--text-3);
  font-style: normal;
}
.vibehub-source .aic-loop-conditions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}
.vibehub-source .aic-loop-conditions span {
  padding: 5px 7px;
  border-radius: 6px;
  background: var(--bg-soft);
  color: var(--text-2);
  font-size: 9px;
  text-align: center;
}

/* TTFT / TPS：第一段等待和之后的生成密度位于同一条时间线上。 */
.vibehub-source .aic-speed-axis {
  min-height: 70px;
  display: grid;
  grid-template-columns: auto minmax(72px, 0.8fr) minmax(130px, 1.3fr) auto;
  align-items: center;
}
.vibehub-source .aic-speed-axis > span {
  position: relative;
  z-index: 1;
}
.vibehub-source .aic-speed-axis .send,.vibehub-source
.aic-speed-axis .done {
  padding: 5px 7px;
  border-radius: 6px;
  background: var(--inverse-bg);
  color: var(--inverse-text);
  font-size: 9px;
}
.vibehub-source .aic-speed-axis .wait {
  height: 2px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--border);
}
.vibehub-source .aic-speed-axis .wait b,.vibehub-source
.aic-speed-axis .wait small,.vibehub-source
.aic-speed-axis .ticks small {
  position: absolute;
  white-space: nowrap;
}
.vibehub-source .aic-speed-axis .wait b {
  top: -24px;
  color: var(--brand);
}
.vibehub-source .aic-speed-axis .wait small {
  top: 7px;
}
.vibehub-source .aic-speed-axis .ticks {
  height: 2px;
  display: flex;
  align-items: center;
  justify-content: space-around;
  background: color-mix(in srgb, var(--brand) 30%, var(--border));
}
.vibehub-source .aic-speed-axis .ticks i {
  width: 7px;
  height: 22px;
  border-radius: 2px;
  background: var(--brand);
}
.vibehub-source .aic-speed-axis .ticks small {
  top: 19px;
  color: var(--brand);
}
.vibehub-source .aic-speed-legend {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 5px;
}
.vibehub-source .aic-speed-legend span {
  padding: 5px;
  border-radius: 5px;
  background: var(--bg-soft);
  color: var(--text-3);
  font-size: 9px;
  text-align: center;
}

/* Token：原句被模型切成不等长片段，输入与输出分别计数。 */
.vibehub-source .aic-token-text {
  align-self: center;
  color: var(--text-2);
  font-size: 13px;
  font-weight: 640;
}
.vibehub-source .aic-token-pieces {
  display: flex;
  justify-content: center;
  gap: 4px;
}
.vibehub-source .aic-token-pieces span {
  padding: 7px 9px;
  border: 1px solid color-mix(in srgb, var(--brand) 24%, var(--border));
  border-radius: 6px;
  background: var(--brand-light);
  color: var(--brand);
  font-family: ui-monospace, monospace;
  font-size: 10px;
}
.vibehub-source .aic-token-pieces span:nth-child(even) {
  transform: translateY(4px);
}
.vibehub-source .aic-token-count {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.vibehub-source .aic-token-count > span {
  display: flex;
  align-items: baseline;
  gap: 5px;
  padding: 5px 8px;
  border-radius: 6px;
  background: var(--bg-soft);
}
.vibehub-source .aic-token-count > i {
  color: var(--text-3);
  font-style: normal;
}

/* Token 成本：逐轮累计输入输出，再按不同单价计算。 */
.vibehub-source .aic-cost-turns {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
}
.vibehub-source .aic-cost-turns span {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 4px;
  padding: 7px;
  border: 1px solid var(--border-light);
  border-radius: 7px;
  background: var(--bg);
}
.vibehub-source .aic-cost-turns span:nth-child(2) {
  border-color: color-mix(in srgb, var(--brand) 22%, var(--border));
}
.vibehub-source .aic-cost-turns span:nth-child(3) {
  border-color: color-mix(in srgb, var(--brand) 34%, var(--border));
}
.vibehub-source .aic-cost-turns span em {
  color: var(--text-3);
  font-size: 9px;
  font-style: normal;
}
.vibehub-source .aic-cost-total {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px;
  border-radius: 7px;
  background: var(--brand-light);
  color: var(--text-2);
  font-size: 9px;
}
.vibehub-source .aic-cost-total i {
  color: var(--text-3);
  font-style: normal;
}
.vibehub-source .aic-cost-total b {
  color: var(--brand);
}

/* 速率限制：队列进入并发闸门，一部分执行，超限请求收到 429。 */
.vibehub-source .aic-rate-main {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto 74px;
  align-items: center;
  gap: 8px;
}
.vibehub-source .aic-rate-queue {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 7px;
  border: 1px solid var(--border-light);
  border-radius: 7px;
  background: var(--bg);
}
.vibehub-source .aic-rate-queue small {
  margin-right: auto;
  color: var(--brand);
}
.vibehub-source .aic-rate-queue span {
  width: 20px;
  height: 20px;
  display: grid;
  place-items: center;
  border-radius: 5px;
  background: var(--bg-soft);
  color: var(--text-2);
  font-size: 9px;
}
.vibehub-source .aic-rate-main > i {
  color: var(--text-3);
  font-style: normal;
}
.vibehub-source .aic-rate-gate {
  display: flex;
  height: 50px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  border: 1px solid color-mix(in srgb, var(--brand) 28%, var(--border));
  border-radius: 8px;
  background: var(--brand-light);
}
.vibehub-source .aic-rate-gate b {
  color: var(--brand);
  font-size: 16px;
}
.vibehub-source .aic-rate-branches {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}
.vibehub-source .aic-rate-branches span {
  padding: 6px 8px;
  border-radius: 6px;
  background: var(--bg-soft);
  font-size: 9px;
  text-align: center;
}

@media (max-width: 420px) {
  .vibehub-source .ai-card-visual {
    gap: 6px;
  }
  .vibehub-source .ai-card-openai-compatible-api {
    padding: 10px 11px;
  }
  .vibehub-source .ai-card-openai-compatible-row {
    grid-template-columns: minmax(0, 1fr) 18px minmax(0, 1fr);
    gap: 6px;
    font-size: 10px;
  }
  .vibehub-source .ai-card-openai-compatible-row > b {
    font-size: 13px;
  }
  .vibehub-source .ai-card-openai-compatible-row > code {
    font-size: 10px;
  }
  .vibehub-source .aic-agent-work {
    grid-template-columns: minmax(94px, 0.8fr) minmax(0, 1.2fr);
  }
  .vibehub-source .aic-harness-frame {
    grid-template-columns: minmax(0, 1fr) minmax(88px, 1.1fr) minmax(0, 1fr);
  }
  .vibehub-source .aic-skill-layout {
    grid-template-columns: minmax(0, 1fr) 54px minmax(0, 1fr);
  }
  .vibehub-source .aic-modal-sides {
    grid-template-columns: minmax(0, 0.8fr) minmax(86px, 1fr) minmax(0, 0.8fr);
  }
  .vibehub-source .aic-vibe-stage {
    grid-template-columns: minmax(0, 1fr) minmax(90px, 1.05fr) minmax(0, 1fr);
  }
  .vibehub-source .aic-rate-queue span:nth-last-child(-n + 2) {
    display: none;
  }
}

/* 提示词：你写的与预设的两层。 */
.vibehub-source .aic-prompt-layer {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px 9px;
  border: 1px solid var(--border-light);
  border-radius: 7px;
  background: var(--bg);
}
.vibehub-source .aic-prompt-layer small {
  flex: none;
  color: var(--text-3);
}
.vibehub-source .aic-prompt-layer.is-user {
  border-color: color-mix(in srgb, var(--brand) 30%, var(--border));
  background: var(--brand-light);
}
.vibehub-source .aic-prompt-layer.is-user small {
  color: var(--brand);
}
.vibehub-source .aic-prompt-layer b {
  font-size: 11px;
  font-weight: 500;
}

/* Base URL：把服务方和可参考文档放在同一张表面上。 */
.vibehub-source .base-url-reference-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.vibehub-source .base-url-reference-row {
  min-width: 0;
}
.vibehub-source .base-url-reference-card {
  min-width: 0;
  height: 100%;
  display: grid;
  align-content: start;
  gap: 10px;
  padding: 14px 15px;
  border: 1px solid var(--border);
  border-radius: 11px;
  color: inherit;
  background: var(--bg);
  text-decoration: none;
}
.vibehub-source .base-url-reference-provider {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  min-width: 0;
}
.vibehub-source .base-url-reference-provider strong {
  min-width: 0;
  color: var(--text);
  font-size: 16px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}
.vibehub-source .base-url-reference-provider span {
  flex: 0 0 auto;
  color: var(--text-3);
  font-size: 13px;
  line-height: 1.4;
  text-align: right;
}
.vibehub-source .base-url-reference-doc {
  display: inline-flex;
  align-items: center;
  justify-self: start;
  gap: 6px;
  min-width: 0;
  max-width: 100%;
  color: var(--brand);
  font-size: 14px;
  font-weight: 650;
  line-height: 1.4;
}
.vibehub-source .base-url-reference-doc span {
  min-width: 0;
  overflow-wrap: anywhere;
}
.vibehub-source .base-url-reference-doc i {
  flex: 0 0 auto;
  font-size: 16px;
  line-height: 1;
}
.vibehub-source .base-url-reference-card:hover {
  border-color: var(--brand);
  background: var(--brand-light);
}
.vibehub-source .base-url-reference-card:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--brand) 60%, transparent);
  outline-offset: 2px;
}
.vibehub-source .detail-entry-base-url .plain-explanation-section {
  max-width: 100%;
}
.vibehub-source .detail-entry-base-url .boundary-note p {
  max-width: none;
}
.vibehub-source .base-url-reference-note {
  max-width: 820px;
  margin: 17px auto 0;
  color: var(--text-2);
  font-size: 14px;
  line-height: 1.65;
  text-align: center;
}

/* 配置文件：用四列对照支持情况、配置位置和官方文档。 */
.vibehub-source .config-file-table-wrap {
  max-width: 100%;
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: 11px;
  background: var(--bg);
}
.vibehub-source .config-file-table {
  width: 100%;
  min-width: 860px;
  border-collapse: collapse;
  table-layout: fixed;
  text-align: left;
}
.vibehub-source .config-file-table th,.vibehub-source
.config-file-table td {
  padding: 13px 14px;
  border-bottom: 1px solid var(--border-light);
  vertical-align: top;
}
.vibehub-source .config-file-table thead th {
  color: var(--text-2);
  background: var(--bg-soft);
  font-size: 12px;
  font-weight: 750;
  line-height: 1.35;
}
.vibehub-source .config-file-table thead th:nth-child(1) {
  width: 18%;
}
.vibehub-source .config-file-table thead th:nth-child(2) {
  width: 19%;
}
.vibehub-source .config-file-table thead th:nth-child(3) {
  width: 45%;
}
.vibehub-source .config-file-table thead th:nth-child(4) {
  width: 18%;
}
.vibehub-source .config-file-table tbody tr:last-child th,.vibehub-source
.config-file-table tbody tr:last-child td {
  border-bottom: 0;
}
.vibehub-source .config-file-table tbody tr:hover th,.vibehub-source
.config-file-table tbody tr:hover td {
  background: color-mix(in srgb, var(--brand-light) 26%, var(--bg));
}
.vibehub-source .config-file-table tbody th {
  color: var(--text);
  font-size: 15px;
  font-weight: 750;
  line-height: 1.45;
  overflow-wrap: anywhere;
