.vibehub-source .md-src { display: flex; flex-direction: column; gap: 3px; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size:12px; color: var(--text-2); }
.vibehub-source .md-out { display: flex; flex-direction: column; gap: 4px; }
