.vibehub-source .md-anat { background: var(--bg); border: 1px solid var(--border); border-radius: 8px; padding: 10px 12px; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 12px; color: var(--text-2); display: flex; flex-direction: column; gap: 2px; }

/* ---- HTML 页面结构 ---- */
.vibehub-source .html-demo { display: flex; align-items: stretch; gap: 8px; width: 100%; }
.vibehub-source .html-tree { flex: 1.1; min-width: 0; display: flex; flex-direction: column; gap: 3px; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 12px; }
