  .route-demo,.vibehub-source
  .sql-demo,.vibehub-source
  .val-demo,.vibehub-source
  .auth-demo,.vibehub-source
  .az-demo {
    max-width: 100%;
  }
  .vibehub-source .fw-pipe {
    grid-template-columns: minmax(0, 1fr);
    gap: 6px;
  }
  .vibehub-source .fw-pipe > i { justify-self: center; transform: rotate(90deg); }
  .vibehub-source .fw-step { min-height: 0; }
  .vibehub-source .route-row {
    grid-template-columns: 48px minmax(0, 1fr);
  }
  .vibehub-source .route-row span {
    grid-column: 2;
    white-space: normal;
  }
  .vibehub-source .sql-query { font-size: 11px; padding: 10px; }
  .vibehub-source .sql-head,.vibehub-source
  .sql-row { grid-template-columns: 28px minmax(0, 1fr) minmax(0, 1fr); }
  .vibehub-source .val-form label {
    grid-template-columns: 40px minmax(0, 1fr);
    gap: 4px 8px;
  }
  .vibehub-source .val-form label > i {
    grid-column: 2;
    justify-self: start;
  }
  .vibehub-source .auth-card { padding: 10px; }
  .vibehub-source .auth-flow { gap: 4px; }
  .vibehub-source .auth-flow span { font-size: 10px; padding: 3px 6px; }
  .vibehub-source .az-who { flex-wrap: wrap; }
  .vibehub-source .dh-demo .fw-step { min-height: 0; padding: 10px 8px; }
}

/* ---- 基础概念目录卡片：保留详情图里的核心关系 ---- */

.vibehub-source .foundation-card-visual {
  width: min(420px, 100%);
  min-width: 0;
  color: var(--text);
  font-size: 11px;
}

.vibehub-source .foundation-card-visual *,.vibehub-source
.foundation-card-visual *::before,.vibehub-source
.foundation-card-visual *::after {
  box-sizing: border-box;
}

.vibehub-source .foundation-card-visual code,.vibehub-source
.foundation-card-visual button,.vibehub-source
.foundation-card-visual input {
  font: inherit;
}

.vibehub-source .foundation-card-visual button {
  border: 0;
  cursor: default;
}

.vibehub-source .fc-foot {
  color: var(--text-3);
  font-size: 10px;
  line-height: 1.35;
  text-align: center;
}

/* Component */
.vibehub-source .fc-component {
  display: grid;
  grid-template-columns: minmax(112px, 0.72fr) minmax(0, 1.28fr);
  gap: 9px 12px;
  align-items: center;
}
.vibehub-source .fc-component-source {
  display: grid;
  gap: 4px;
  padding: 11px;
  border: 1px solid color-mix(in srgb, var(--brand) 35%, var(--border));
  border-radius: 9px;
  background: var(--brand-light);
}
.vibehub-source .fc-component-source small,.vibehub-source
.fc-component-pages small {
  color: var(--text-3);
  font-size: 9px;
}
.vibehub-source .fc-component-source b {
  color: var(--brand);
  font-size: 13px;
}
.vibehub-source .fc-component-source code {
  color: var(--text-2);
  font-size: 9px;
}
.vibehub-source .fc-component-pages {
  display: grid;
  grid-template-columns: 1fr 12px 1fr;
  align-items: center;
  gap: 4px;
}
.vibehub-source .fc-component-pages span {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 10px 8px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
}
.vibehub-source .fc-component-pages span b {
  overflow: hidden;
  font-size: 9px;
  text-overflow: ellipsis;
}
.vibehub-source .fc-component-pages i {
  height: 1px;
  background: var(--brand);
}
.vibehub-source .fc-component .fc-foot {
  grid-column: 1 / -1;
}

/* State */
.vibehub-source .fc-state {
  display: grid;
  gap: 9px;
}
.vibehub-source .fc-state-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 4px 8px;
  padding: 9px 11px;
  border: 1px solid var(--border);
  border-radius: 9px;
  background: var(--bg);
}
.vibehub-source .fc-state-form small {
  grid-column: 1 / -1;
  color: var(--text-3);
  font-size: 9px;
}
.vibehub-source .fc-state-form b {
  align-self: center;
}
.vibehub-source .fc-state-form button {
  padding: 4px 8px;
  border-radius: 6px;
  color: var(--green);
  background: var(--green-light);
}
.vibehub-source .fc-state-track {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  flex-wrap: wrap;
}
.vibehub-source .fc-state-track span {
  padding: 4px 6px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg);
  white-space: nowrap;
}
.vibehub-source .fc-state-track i,.vibehub-source
.fc-state-track em {
  color: var(--text-3);
  font-size: 9px;
  font-style: normal;
}
.vibehub-source .fc-state-track .ok {
  border-color: color-mix(in srgb, var(--green) 35%, var(--border));
  color: var(--green);
  background: var(--green-light);
}
.vibehub-source .fc-state-track .fail {
  color: var(--red);
  background: var(--red-light);
}

/* Port */
.vibehub-source .fc-port {
  display: grid;
  gap: 8px;
}
.vibehub-source .fc-port-address {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
}
.vibehub-source .fc-port-address code {
  padding: 5px 9px;
  border-radius: 6px;
  color: var(--brand);
  background: var(--brand-light);
