}
.vibehub-source .fc-port-address b {
  color: var(--text-2);
  font-size: 10px;
}
.vibehub-source .fc-port-sockets {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
}
.vibehub-source .fc-port-sockets span {
  display: grid;
  justify-items: center;
  gap: 4px;
  padding: 9px 5px;
  border: 1px solid var(--border);
  border-radius: 8px;
