}
.vibehub-source .fc-port-sockets span.active {
  border-color: color-mix(in srgb, var(--brand) 42%, var(--border));
  background: var(--brand-light);
}
.vibehub-source .fc-port-sockets code {
  color: var(--brand);
  font-weight: 700;
}
.vibehub-source .fc-port-sockets b {
  color: var(--text-2);
  font-size: 10px;
}

/* Box model */
