}
.vibehub-source .fc-chart-bars span.max i {
  background: var(--brand);
}
.vibehub-source .fc-chart-bars small {
  color: var(--text-3);
  font-size: 8px;
}
.vibehub-source .fc-chart-bars span b {
  position: absolute;
  top: 0;
  color: var(--brand);
  font-size: 9px;
}

/* Dark mode */
.vibehub-source .fc-dark-mode {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 7px;
}
.vibehub-source .fc-dark-mode > i {
  color: var(--brand);
  font-style: normal;
}
.vibehub-source .fc-theme {
  display: grid;
  gap: 5px;
  padding: 9px;
  border: 1px solid #d8dce5;
  border-radius: 8px;
  color: #20232b;
  background: var(--bg);
}
.vibehub-source .fc-theme small {
  color: #6b7280;
  font-size: 9px;
}
.vibehub-source .fc-theme span {
  font-size: 9px;
}
.vibehub-source .fc-theme button {
  justify-self: start;
  padding: 4px 7px;
  border-radius: 5px;
  color: #fff;
  background: #3156d3;
}
.vibehub-source .fc-theme.dark {
  border-color: #3d4452;
  color: #f3f4f6;
  background: #171a21;
}
.vibehub-source .fc-theme.dark small,.vibehub-source
.fc-theme.dark span {
  color: #aeb4c0;
}
.vibehub-source .fc-dark-mode .fc-foot {
  grid-column: 1 / -1;
}

/* Design token */
.vibehub-source .fc-design-token {
  display: grid;
  gap: 0;
}
.vibehub-source .fc-token-source {
  justify-self: center;
  display: grid;
  gap: 3px;
  padding: 6px 10px;
  border: 1px solid color-mix(in srgb, var(--brand) 35%, var(--border));
  border-radius: 7px;
  background: var(--brand-light);
}
.vibehub-source .fc-token-source small {
  color: var(--text-3);
  font-size: 8px;
}
.vibehub-source .fc-token-source code {
  color: var(--brand);
  font-size: 9px;
  font-weight: 700;
}
.vibehub-source .fc-token-links {
  width: 68%;
  height: 15px;
  justify-self: center;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}
.vibehub-source .fc-token-links i {
  border-top: 1px solid var(--brand);
  border-left: 1px solid var(--brand);
}
.vibehub-source .fc-token-links i:last-child {
  border-right: 1px solid var(--brand);
}
.vibehub-source .fc-token-components {
  display: grid;
  grid-template-columns: 0.75fr 1fr 1fr;
  align-items: stretch;
  gap: 6px;
}
.vibehub-source .fc-token-components button,.vibehub-source
.fc-token-components label,.vibehub-source
.fc-token-components article {
  min-width: 0;
  padding: 7px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--bg);
}
.vibehub-source .fc-token-components button {
  align-self: center;
  color: white;
  background: var(--brand);
}
.vibehub-source .fc-token-components label {
  display: grid;
  gap: 3px;
  color: var(--text-3);
  font-size: 8px;
}
.vibehub-source .fc-token-components input {
  min-width: 0;
  width: 100%;
  border: 0;
  color: var(--text);
  background: transparent;
  font-size: 9px;
}
.vibehub-source .fc-token-components article {
  display: grid;
  gap: 3px;
  border-color: var(--brand);
}
.vibehub-source .fc-token-components article small {
  color: var(--brand);
  font-size: 8px;
}
.vibehub-source .fc-token-components article b {
  overflow: hidden;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.vibehub-source .fc-design-token .fc-foot {
  margin-top: 6px;
}

@media (max-width: 560px) {
  .vibehub-source .fc-component,.vibehub-source
  .fc-box-model,.vibehub-source
  .fc-overflow,.vibehub-source
  .fc-seo {
    grid-template-columns: minmax(0, 1fr);
  }
  .vibehub-source .fc-component .fc-foot,.vibehub-source
  .fc-box-model .fc-foot,.vibehub-source
  .fc-seo .fc-foot {
    grid-column: 1;
  }
  .vibehub-source .fc-overflow-note {
    grid-template-columns: 1fr auto 1fr;
    align-items: center;
  }
  .vibehub-source .fc-redirect-network {
    gap: 3px;
  }
  .vibehub-source .fc-redirect-network span {
    padding: 5px 3px;
  }
}

/* Server log */
.vibehub-source .server-log-mini {
  width: min(420px, 100%);
  overflow: hidden;
  display: grid;
  border: 1px solid var(--border);
  border-radius: 9px;
  color: var(--text);
  background: var(--bg);
  font: 10px/1.35 ui-monospace, SFMono-Regular, Menlo, monospace;
}
.vibehub-source .server-log-mini-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 9px;
  border-bottom: 1px solid var(--border-light);
  background: var(--bg-soft);
}
.vibehub-source .server-log-mini-head code { color: var(--brand); }
.vibehub-source .server-log-mini-lines { display: grid; padding: 5px 9px; }
.vibehub-source .server-log-mini-lines span {
  display: grid;
  grid-template-columns: 52px minmax(80px, 1fr) minmax(90px, 1.2fr);
  gap: 7px;
  padding: 4px 0;
  color: var(--text-2);
  border-bottom: 1px solid var(--border-light);
}
.vibehub-source .server-log-mini-lines span:last-child { border-bottom: 0; }
.vibehub-source .server-log-mini-lines i { color: var(--text-3); font-style: normal; }
.vibehub-source .server-log-mini-lines code {
  overflow: hidden;
  color: var(--brand);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.vibehub-source .server-log-mini-lines .ok b,.vibehub-source
.server-log-mini-lines .ok code { color: var(--green); }
.vibehub-source .server-log-mini > small {
  padding: 5px 9px;
  color: var(--text-3);
  background: var(--bg-soft);
  text-align: center;
}

/* domains/platform/testing-delivery.css */
/* 测试与交付：图解使用真实业务界面，不使用通用概念卡片。 */
.vibehub-source .testing-visual {
  --td-ink: var(--text);
  --td-muted: var(--text-2);
  --td-faint: var(--bg-soft);
  --td-line: var(--border);
  --td-pass: var(--green);
  --td-pass-soft: var(--green-light);
  --td-blue: var(--info);
  --td-blue-soft: var(--info-light);
  --td-alert: var(--red);
  --td-alert-soft: var(--red-light);
  width: 100%;
  color: var(--td-ink);
}
.vibehub-source .td-stage { outline: none; }
.vibehub-source .td-stage:focus-visible { outline: 3px solid #9eb8ef; outline-offset: 6px; border-radius: 8px; }
.vibehub-source .td-controls { display: flex; gap: 24px; margin: 0 0 22px; border-bottom: 1px solid var(--td-line); }
.vibehub-source .td-controls button {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 46px;
  padding: 0 0 12px;
  border: 0;
  border-bottom: 2px solid transparent;
  color: var(--td-muted);
  background: transparent;
  font: 620 15px/1.3 ui-sans-serif, system-ui, sans-serif;
  cursor: pointer;
}
.vibehub-source .td-controls button span { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; color: var(--td-muted); background: var(--bg-hover); font-size: 13px; }
.vibehub-source .td-controls button:hover,.vibehub-source  .td-controls button:focus-visible { color: var(--td-ink); }
.vibehub-source .td-controls button:focus-visible { outline: 2px solid #9eb8ef; outline-offset: 4px; }
.vibehub-source .td-controls button.is-active { color: var(--td-ink); border-bottom-color: var(--td-ink); }
.vibehub-source .td-controls button.is-active span { color: var(--inverse-text); background: var(--inverse-bg); }
.vibehub-source .td-evidence,.vibehub-source  .td-evidence * { box-sizing: border-box; }
.vibehub-source .td-evidence :is(p, span, b, strong, code, small, li, dd) { overflow-wrap: anywhere; }
.vibehub-source .td-proof { display: flex; gap: 9px; margin: 0; padding: 16px 20px 18px; color: var(--td-muted); font-size: 16px; line-height: 1.65; }
.vibehub-source .td-proof i { flex: 0 0 auto; color: var(--td-ink); font-style: normal; font-weight: 800; }
.vibehub-source .td-app,.vibehub-source  .td-workbench,.vibehub-source  .td-deploy-console,.vibehub-source  .td-repo-page,.vibehub-source  .td-data-console,.vibehub-source  .td-flow-map,.vibehub-source  .td-observability,.vibehub-source  .td-flag-console {
  width: 100%;
  overflow: hidden;
  border: 1px solid var(--td-line);
  border-radius: 12px;
  background: var(--bg);
}
.vibehub-source .td-browser-bar {
  display: grid;
  grid-template-columns: 10px 10px 10px minmax(0, 1fr) auto;
  align-items: center;
  gap: 7px;
  min-height: 44px;
  padding: 8px 14px;
  border-bottom: 1px solid var(--td-line);
  background: var(--td-faint);
}
.vibehub-source .td-browser-bar > i { width: 9px; height: 9px; border-radius: 50%; background: var(--bg-hover); }
.vibehub-source .td-browser-bar code { margin-left: 6px; padding: 5px 10px; border-radius: 6px; color: var(--td-muted); background: var(--bg); font: 14px/1.3 ui-monospace, SFMono-Regular, Menlo, monospace; }
.vibehub-source .td-browser-bar b { padding: 4px 8px; border-radius: 5px; color: var(--td-ink); background: var(--bg-hover); font-size: 13px; }
.vibehub-source .td-tick { display: flex; align-items: flex-start; gap: 9px; color: var(--td-muted); font-size: 15px; line-height: 1.5; }
.vibehub-source .td-tick i { display: grid; place-items: center; flex: 0 0 20px; height: 20px; margin-top: 1px; border-radius: 50%; color: var(--text-2); background: var(--bg-hover); font: 700 13px/1 sans-serif; }
.vibehub-source .td-tick.is-pass { color: var(--td-ink); }
.vibehub-source .td-tick.is-pass i { color: var(--on-status); background: var(--td-pass); }
.vibehub-source .td-tick.is-fail { color: var(--td-alert); font-weight: 700; }
.vibehub-source .td-tick.is-fail i { color: var(--on-status); background: var(--td-alert); }

/* 验收标准 */
.vibehub-source .td-acceptance-body { display: grid; grid-template-columns: minmax(250px, .72fr) minmax(0, 1.28fr); min-height: 330px; }
.vibehub-source .td-criteria-list { display: grid; align-content: start; gap: 22px; padding: 28px; border-right: 1px solid var(--td-line); background: var(--bg-hover); }
.vibehub-source .td-criteria-list small { color: var(--td-muted); font: 700 13px/1.3 ui-monospace, monospace; letter-spacing: .08em; }
.vibehub-source .td-itinerary { padding: 28px 32px; }
.vibehub-source .td-itinerary-title { display: flex; justify-content: space-between; gap: 20px; margin-bottom: 26px; }
.vibehub-source .td-itinerary-title span { font-size: 21px; font-weight: 750; }
.vibehub-source .td-itinerary-title b { font-size: 18px; }
.vibehub-source .td-trip-line { display: grid; grid-template-columns: 48px 16px minmax(0, 1fr); gap: 10px; min-height: 72px; }
.vibehub-source .td-trip-line time { color: var(--td-muted); font: 14px/1.4 ui-monospace, monospace; }
.vibehub-source .td-trip-line > i { position: relative; width: 10px; height: 10px; margin-top: 4px; border: 2px solid var(--td-ink); border-radius: 50%; }
.vibehub-source .td-trip-line:first-of-type > i::after { position: absolute; top: 9px; left: 2px; width: 2px; height: 54px; background: var(--td-line); content: ""; }
.vibehub-source .td-trip-line span { display: grid; align-content: start; gap: 4px; }
.vibehub-source .td-trip-line b { font-size: 16px; }
.vibehub-source .td-trip-line small { color: var(--td-muted); font-size: 14px; }
.vibehub-source .td-date-note { display: flex; gap: 9px; padding-top: 16px; border-top: 1px solid var(--td-line); color: var(--td-alert); font-size: 15px; }
.vibehub-source .td-date-note b { display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; color: var(--on-status); background: var(--td-alert); }
.vibehub-source .td-date-note.is-valid { color: var(--td-pass); }
.vibehub-source .td-date-note.is-valid b { background: var(--td-pass); }

/* 测试用例 */
.vibehub-source .td-login-scene { display: grid; grid-template-columns: minmax(250px, .9fr) minmax(300px, 1.1fr); min-height: 350px; }
.vibehub-source .td-login-scene > aside { display: grid; align-content: start; gap: 9px; padding: 32px; background: var(--td-faint); }
.vibehub-source .td-login-scene > aside > small { color: var(--td-muted); font: 700 13px/1.3 ui-monospace, monospace; letter-spacing: .08em; }
.vibehub-source .td-login-scene > aside > b { margin-top: 8px; font-size: 18px; }
.vibehub-source .td-login-scene > aside > span { color: var(--td-muted); font-size: 15px; }
.vibehub-source .td-login-scene dl { display: grid; gap: 18px; margin: 24px 0 0; }
.vibehub-source .td-login-scene dl div { display: grid; gap: 5px; }
.vibehub-source .td-login-scene dt { color: var(--td-muted); font-size: 14px; }
.vibehub-source .td-login-scene dd { margin: 0; font-size: 15px; font-weight: 650; }
.vibehub-source .td-login-scene form { display: grid; align-content: start; gap: 15px; padding: 32px clamp(28px, 6vw, 72px); }
.vibehub-source .td-login-scene h3 { margin: 0 0 8px; font-size: 22px; }
.vibehub-source .td-login-scene label { display: grid; gap: 7px; color: var(--td-muted); font-size: 14px; }
.vibehub-source .td-login-scene label span { min-height: 44px; padding: 11px 12px; border: 1px solid #bdc2c8; border-radius: 7px; color: var(--td-ink); background: var(--bg); font-size: 15px; }
.vibehub-source .td-login-scene button,.vibehub-source  .td-booking-form button,.vibehub-source  .td-trip-product button,.vibehub-source  .td-checkout button,.vibehub-source  .td-receipt button {
  min-height: 44px;
  border: 0;
  border-radius: 7px;
  color: var(--inverse-text);
  background: var(--inverse-bg);
  font-size: 15px;
  font-weight: 700;
}
.vibehub-source .td-form-error { margin: -4px 0 0; color: var(--td-alert); font-size: 14px; line-height: 1.45; }

/* 编辑器、终端与通用工作区 */
.vibehub-source .td-workbench > header,.vibehub-source  .td-data-console > header,.vibehub-source  .td-flow-map > header,.vibehub-source  .td-observability > header,.vibehub-source  .td-flag-console > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 48px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--td-line);
  background: var(--td-faint);
}
.vibehub-source .td-workbench > header b,.vibehub-source  .td-data-console > header b,.vibehub-source  .td-flow-map > header b,.vibehub-source  .td-observability > header b { font: 700 15px/1.4 ui-monospace, monospace; }
.vibehub-source .td-workbench > header span,.vibehub-source  .td-data-console > header span,.vibehub-source  .td-flow-map > header span,.vibehub-source  .td-observability > header span { color: var(--td-muted); font-size: 14px; }
.vibehub-source .td-editor-layout { display: grid; grid-template-columns: 150px minmax(0, 1fr); min-height: 230px; }
.vibehub-source .td-editor-layout nav,.vibehub-source  .td-build-layout nav { display: grid; align-content: start; gap: 8px; padding: 18px 14px; border-right: 1px solid var(--td-line); background: var(--bg-hover); }
.vibehub-source .td-editor-layout nav :is(span, b),.vibehub-source  .td-build-layout nav :is(span, b) { padding: 4px 8px; font: 14px/1.4 ui-monospace, monospace; }
.vibehub-source .td-editor-layout nav span { color: var(--td-muted); }
.vibehub-source .td-editor-layout nav b { padding-left: 18px; }
.vibehub-source .td-editor-layout nav .is-selected { border-radius: 4px; background: var(--bg-hover); }
.vibehub-source .td-editor-layout pre,.vibehub-source  .td-terminal-panel,.vibehub-source  .td-build-layout pre,.vibehub-source  .td-double-layout pre,.vibehub-source  .td-lint-layout pre {
  margin: 0;
  color: #e4e9ef;
  background: #24282d;
  font: 15px/1.75 ui-monospace, SFMono-Regular, Menlo, monospace;
}
.vibehub-source .td-editor-layout pre,.vibehub-source  .td-build-layout pre,.vibehub-source  .td-double-layout pre,.vibehub-source  .td-lint-layout pre { padding: 22px; overflow: auto; }
.vibehub-source .td-editor-layout em,.vibehub-source  .td-lint-layout pre em { display: inline-block; width: 28px; color: var(--text-2); font-style: normal; user-select: none; }
.vibehub-source .td-editor-layout mark { padding: 1px 3px; color: #fff; background: #4a525d; }
.vibehub-source .td-terminal-panel { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 6px 18px; padding: 14px 18px; border-top: 1px solid #3b4148; }
.vibehub-source .td-terminal-panel span { color: #aab3bd; font-size: 14px; }
.vibehub-source .td-terminal-panel b { color: #fff; font-size: 14px; }
.vibehub-source .td-terminal-panel small { grid-column: 1 / -1; color: #9aa3ad; font-size: 13px; }

/* 集成测试 */
.vibehub-source .td-integration-grid { display: grid; grid-template-columns: .8fr 1.2fr; }
.vibehub-source .td-integration > header code { color: var(--td-muted); font-size: 14px; }
.vibehub-source .td-booking-form { display: grid; align-content: start; gap: 14px; min-height: 270px; padding: 26px; border-right: 1px solid var(--td-line); }
.vibehub-source .td-booking-form label { display: grid; gap: 7px; color: var(--td-muted); font-size: 14px; }
.vibehub-source .td-booking-form label span { padding: 10px 11px; border: 1px solid var(--td-line); border-radius: 6px; color: var(--td-ink); font-size: 15px; }
.vibehub-source .td-network-pane { min-height: 270px; padding: 24px; color: #dfe5ec; background: #24282d; }
.vibehub-source .td-network-pane small,.vibehub-source  .td-record-table small { display: block; margin-bottom: 12px; color: #9fa8b3; font: 700 13px/1.3 ui-monospace, monospace; }
.vibehub-source .td-network-pane b { display: inline-block; margin-bottom: 12px; color: #aab3bd; font: 650 14px/1.4 ui-monospace, monospace; }
