.vibehub-source .td-record-table { grid-column: 1 / -1; padding: 18px 24px 22px; border-top: 1px solid var(--td-line); }
.vibehub-source .td-table-head,.vibehub-source  .td-table-row { display: grid; grid-template-columns: .8fr 1.2fr 1fr; gap: 12px; padding: 9px 12px; font-size: 14px; }
.vibehub-source .td-table-head { color: var(--td-muted); background: var(--td-faint); }
.vibehub-source .td-table-row { border-bottom: 1px solid var(--td-line); }
.vibehub-source .td-table-row.is-new { background: var(--td-pass-soft); }
.vibehub-source .td-table-empty { padding: 14px 12px; color: var(--td-muted); font-size: 14px; }

/* E2E */
.vibehub-source .td-journey { padding: 22px 28px 28px; }
.vibehub-source .td-journey ol { display: grid; grid-template-columns: repeat(3, 1fr); margin: 0 0 28px; padding: 0; list-style: none; }
.vibehub-source .td-journey li { position: relative; color: var(--td-muted); font-size: 14px; text-align: center; }
.vibehub-source .td-journey li::before { display: block; width: 12px; height: 12px; margin: 0 auto 8px; border-radius: 50%; background: var(--bg-hover); content: ""; }
.vibehub-source .td-journey li:not(:last-child)::after { position: absolute; top: 5px; left: calc(50% + 10px); width: calc(100% - 20px); height: 2px; background: var(--bg-hover); content: ""; }
.vibehub-source .td-journey li.is-done { color: var(--td-ink); font-weight: 700; }
