.vibehub-source .td-trip-product,.vibehub-source  .td-confirmation { min-height: 220px; padding: 30px; background: linear-gradient(120deg, #f5f1e9 0 54%, #e1e5df 54%); }
.vibehub-source .td-trip-product > span { font-size: 13px; font-weight: 800; letter-spacing: .08em; }
