/* 契约测试 */
.vibehub-source .td-contract-board { padding: 22px; }
.vibehub-source .td-contract-step { max-width: 780px; margin: 0 auto; }
.vibehub-source .td-contract-step > .td-badge { display: block; margin-bottom: 14px; color: var(--td-muted); font-size: 14px; font-weight: 750; }
.vibehub-source .td-contract-step > .td-badge.is-warn,.vibehub-source  .td-contract-step > .td-badge.is-fail { color: var(--td-alert); }
.vibehub-source .td-contract-pair { display: grid; grid-template-columns: minmax(0, 1fr) 30px minmax(0, 1fr); align-items: stretch; gap: 10px; }
.vibehub-source .td-contract-pair > section { min-width: 0; overflow: hidden; border: 1px solid var(--td-line); border-radius: 8px; background: var(--td-faint); }
.vibehub-source .td-contract-pair > section.is-broken { border-color: #e2a8ac; background: var(--td-alert-soft); }
.vibehub-source .td-contract-pair > section small { display: block; padding: 10px 13px; border-bottom: 1px solid var(--td-line); color: var(--td-muted); background: var(--bg); font-size: 14px; font-weight: 750; }
.vibehub-source .td-contract-pair pre { min-height: 150px; margin: 0; padding: 16px; overflow: auto; color: var(--td-ink); font: 14px/1.65 ui-monospace, SFMono-Regular, Menlo, monospace; white-space: pre-wrap; }
.vibehub-source .td-contract-pair > i { display: grid; place-items: center; color: var(--td-muted); font-size: 21px; font-style: normal; }
.vibehub-source .td-contract-checks { overflow: hidden; border: 1px solid var(--td-line); border-radius: 9px; background: var(--bg); }
.vibehub-source .td-contract-checks > header { display: flex; justify-content: space-between; gap: 16px; padding: 13px 16px; border-bottom: 1px solid var(--td-line); background: var(--td-faint); font-size: 14px; }
.vibehub-source .td-contract-checks > header b { color: var(--td-alert); }
.vibehub-source .td-contract-result { display: grid; gap: 8px; margin: 18px; padding: 16px; border-radius: 7px; font-size: 14px; line-height: 1.55; }
.vibehub-source .td-contract-result.is-failed { color: var(--td-alert); background: var(--td-alert-soft); }
.vibehub-source .td-contract-result code { overflow-wrap: anywhere; color: inherit; font: 14px/1.55 ui-monospace, SFMono-Regular, Menlo, monospace; }
.vibehub-source .td-contract-checks > button { display: block; min-width: 150px; min-height: 42px; margin: 0 18px 18px auto; border: 0; border-radius: 6px; color: var(--text-2); background: var(--bg-hover); font-size: 14px; font-weight: 750; }

@media (max-width: 520px) {
  .vibehub-source .td-contract-board { padding: 16px; }
  .vibehub-source .td-contract-pair { grid-template-columns: 1fr; }
  .vibehub-source .td-contract-pair > i { min-height: 26px; font-size: 0; }
  .vibehub-source .td-contract-pair > i::before { content: "↓"; font-size: 21px; }
}

/* domains/design/modern-styles.css */
/* modern styles module：设计风格（style-minimal / style-apple / style-notion / style-bento / style-glass / style-brutalism / style-swiss / style-editorial） */

/* ===== style-minimal 现代简约 ===== */
.vibehub-source .style-minimal-demo {
  width: 100%; background: #fff; border: 1px solid #ececf0; border-radius: 14px; overflow: hidden;
}
.vibehub-source .style-minimal-nav {
  display: flex; align-items: center; gap: 14px; padding: 9px 18px;
  border-bottom: 1px solid #f0f0f3; font-size: 12px; color: #61616a;
}
