.vibehub-source .style-minimal-logo i { width: 13px; height: 13px; border-radius: 4px; background: linear-gradient(135deg, #5e6ad2, #9aa5f5); display: block; }
.vibehub-source .style-minimal-login { margin-left: auto; }
.vibehub-source .style-minimal-navbtn { background: #0a0a0c; color: #fff; border-radius: 6px; padding: 4px 10px; font-size: 12px; font-weight: 600; }
.vibehub-source .style-minimal-hero { padding: 24px 22px 20px; text-align: center; }
.vibehub-source .style-minimal-pill {
  display: inline-flex; align-items: center; gap: 5px; border: 1px solid #e8e8ec; border-radius: 999px;
  padding: 3px 10px; font-size: 12px; color: #61616a; background: #fafafb;
}
.vibehub-source .style-minimal-pill b { color: #5e6ad2; font-weight: 600; }
.vibehub-source .style-minimal-h1 { font-size: 30px; line-height: 1.16; letter-spacing: -1.2px; font-weight: 700; color: #0a0a0c; margin: 12px 0 0; }
.vibehub-source .style-minimal-h1 span { color: #a9a9b2; }
.vibehub-source .style-minimal-sub { font-size: 13px; color: #6d6d76; margin: 10px 0 0; }
.vibehub-source .style-minimal-actions { display: flex; justify-content: center; gap: 10px; margin-top: 15px; }
.vibehub-source .style-minimal-btn { background: #0a0a0c; color: #fff; font-size: 12px; font-weight: 600; border-radius: 7px; padding: 7px 15px; }
