.vibehub-source .style-minimal-feat b { display: block; font-size: 12px; color: #0a0a0c; }
.vibehub-source .style-minimal-feat span { font-size: 12px; color: #8a8a93; }
/* anatomy 通用配方 chips（各风格共用结构，配色各自内联） */
.vibehub-source .style-minimal-chip,.vibehub-source  .style-apple-chip,.vibehub-source  .style-notion-chip,.vibehub-source  .style-bento-chip,.vibehub-source
.style-glass-chip,.vibehub-source  .style-brutalism-chip,.vibehub-source  .style-swiss-chip,.vibehub-source  .style-editorial-chip {
  display: inline-flex; align-items: center; gap: 7px;
