}
.vibehub-source .style-minimal-chip i,.vibehub-source  .style-apple-chip i,.vibehub-source  .style-notion-chip i,.vibehub-source  .style-bento-chip i,.vibehub-source
.style-glass-chip i,.vibehub-source  .style-brutalism-chip i,.vibehub-source  .style-swiss-chip i,.vibehub-source  .style-editorial-chip i {
  width: 16px; height: 16px; border-radius: 5px; display: block; flex: none;
