/* expressive styles module:个性风格(Y2K 千禧 / 孟菲斯 / 终端极客 / 日式侘寂) */


/* ==================== Y2K 千禧 ==================== */
.vibehub-source .style-y2k-demo {
  position: relative; overflow: hidden; border-radius: 10px;
  min-height: 196px; padding: 22px;
  display: flex; align-items: center; justify-content: center;
  background: linear-gradient(155deg, #bfe3ff 0%, #e3f2ff 38%, #ffd9ef 78%, #ffc2e4 100%);
}
/* 彩虹渐变光斑 */
.vibehub-source .style-y2k-blob {
  position: absolute; border-radius: 50%; filter: blur(2px); opacity: .8;
  background: conic-gradient(from 210deg, #a8e6ff, #ffd1ec, #fff3b0, #c3f5e8, #a8e6ff);
}
.vibehub-source .style-y2k-star {
  position: absolute; color: #fff; font-style: normal;
  text-shadow: 0 0 8px rgba(255,158,214,.95), 0 1px 2px rgba(150,110,200,.55);
}
/* 金属渐变文字 */
.vibehub-source .style-y2k-chrome {
  display: inline-block;
  font-size: 32px; font-weight: 800; font-style: italic; letter-spacing: 1px;
  background: linear-gradient(180deg, #feffff 0%, #c7d3e3 28%, #67768c 47%, #eef4fb 53%, #93a5bc 74%, #f7fbff 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 2px 0 rgba(255,255,255,.95)) drop-shadow(0 4px 8px rgba(105,90,160,.4));
}
.vibehub-source .style-y2k-bubble {
  display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: 1px;
  color: #fff; padding: 8px 18px; border-radius: 999px;
  border: 1px solid rgba(255,255,255,.75);
  background: linear-gradient(180deg, #ffc9e5 0%, #ff8fc7 46%, #f556a8 100%);
  box-shadow: inset 0 2px 2px rgba(255,255,255,.9), inset 0 -3px 5px rgba(190,20,110,.4), 0 5px 12px rgba(245,86,168,.45);
}
.vibehub-source .style-y2k-bubble.blue {
  background: linear-gradient(180deg, #c9ecff 0%, #7ec8f5 46%, #3d9fe8 100%);
  box-shadow: inset 0 2px 2px rgba(255,255,255,.9), inset 0 -3px 5px rgba(20,90,170,.4), 0 5px 12px rgba(61,159,232,.45);
}
/* 配方拆解 */
.vibehub-source .style-y2k-anat { display: inline-flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.vibehub-source .style-y2k-sw {
  display: inline-flex; align-items: center; justify-content: center;
  width: 74px; height: 44px; border-radius: 6px; border: 1px solid var(--border-light);
  font-size: 12px; color: var(--text-2); overflow: hidden;
}
