.vibehub-source .gd-stage.dim { opacity: .45; }
/* 存档点：本地/远程仓库里的一排小圆点 */
.vibehub-source .gd-dots { display: flex; gap: 4px; margin-top: 2px; }
.vibehub-source .gd-dots i { width: 7px; height: 7px; border-radius: 50%; background: var(--border); }
.vibehub-source .gd-dots i.on { background: var(--brand); }
