.vibehub-source .gd-arrow.green { color: var(--green); font-weight: 700; }
.vibehub-source .gd-arrow.green code { color: color-mix(in srgb, var(--green) 80%, #000); }

/* ---- 分支图：每条 lane 一条线，圆点是存档 ---- */
.vibehub-source .gd-lanes { display: flex; flex-direction: column; gap: 10px; width: 100%; }
.vibehub-source .gd-lane { display: flex; align-items: center; gap: 0; }
