.vibehub-source .gd-tag.gray { color: var(--text-3); background: var(--bg-soft); border-color: var(--border-light); }
.vibehub-source .gd-dot { flex: none; width: 9px; height: 9px; border-radius: 50%; background: var(--brand); }
.vibehub-source .gd-dot.green { background: var(--green); }
.vibehub-source .gd-dot.purple { background: #7c5ce0; }
