}
.vibehub-source .gd-cmd b { color: #8b93a5; font-weight: 400; margin-right: 6px; }
.vibehub-source .gd-cmd .hl { color: #7ee787; }

/* ---- 人话注解：详情图下方一行，加粗处给结论 ---- */
.vibehub-source .gd-note { font-size: 12.5px; line-height: 1.65; color: var(--text-2); }
.vibehub-source .gd-note b { color: var(--text); font-weight: 650; }
.vibehub-source .gd-note .bad { color: var(--red); font-weight: 650; }

/* ---- 两栏对比（diff / before-after 用） ---- */
.vibehub-source .gd-cols { display: flex; gap: 8px; width: 100%; }
.vibehub-source .gd-col {
  flex: 1 1 0; min-width: 0;
  border: 1.5px solid var(--border); border-radius: 10px; background: var(--bg);
  padding: 9px 10px; display: flex; flex-direction: column; gap: 4px;
}
.vibehub-source .gd-col > b { font-size: 11.5px; font-weight: 650; color: var(--text-2); }
.vibehub-source .gd-col small { font-size: 11px; color: var(--text-3); line-height: 1.5; }
.vibehub-source .gd-col.on { border-color: var(--brand); background: var(--brand-light); }
.vibehub-source .gd-col.green { border-color: color-mix(in srgb, var(--green) 55%, var(--border)); background: var(--green-light); }
.vibehub-source .gd-col.red { border-color: color-mix(in srgb, var(--red) 45%, var(--border)); background: var(--red-light); }

/* 详情页演示容器里让图示居中且不被拉得过宽 */
.vibehub-source .detail-hero .gd,.vibehub-source  .dh-demo-inner .gd { max-width: 560px; margin: 0 auto; }

/* ---- 2026 Git story visuals -------------------------------------------------
   One visual sentence per card. Chinese action/result copy leads; commands sit
   in a quiet secondary row on detail pages. */
.vibehub-source .git-story {
  --git-ink: var(--text);
  --git-blue: var(--brand);
  --git-blue-soft: var(--brand-light);
  --git-green: var(--green);
  --git-green-soft: var(--green-light);
  --git-purple: var(--code-keyword);
  width: min(100%, 650px);
  color: var(--git-ink);
}
.vibehub-source .git-story-main { width: 100%; }
.vibehub-source .git-story.is-card { min-height: 104px; display: grid; place-items: center; }
.vibehub-source .git-story.is-detail {
  display: grid;
  gap: 24px;
  width: 100%;
}
.vibehub-source .git-story.is-detail .git-story-main {
  min-height: 152px; display: grid; align-items: center;
  padding: 20px 22px; border: 1px solid #e8ebf0; border-radius: 14px;
  background: linear-gradient(180deg, #fff, #fbfcfe);
  box-shadow: 0 1px 0 rgba(27,31,36,.03);
}
.vibehub-source .git-story.is-detail :is(
  .git-branch-visual,
  .git-merge-visual,
  .git-worktree-visual,
  .git-stash-visual,
  .git-ignore-visual,
  .git-diff-visual
) {
  width: 100%;
  max-width: none;
}
.vibehub-source .git-story-answer {
  display: grid; grid-template-columns: max-content minmax(0, 1fr); align-items: start; gap: 16px;
  padding-top: 18px; border-top: 1px solid var(--border-light);
}
.vibehub-source .git-command {
  display: inline-flex; align-items: center; min-height: 28px; max-width: 100%;
  padding: 5px 9px; border: 1px solid #dfe3e8; border-radius: 7px;
  color: var(--text-2); background: var(--bg-soft);
  font: 600 11px/1.45 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  white-space: nowrap;
}
.vibehub-source .git-story-answer p { margin: 1px 0 0; color: var(--text-2); font-size: 13px; line-height: 1.75; }

.vibehub-source .git-simple-flow,.vibehub-source
.git-transfer-visual,.vibehub-source
.git-review-visual {
  display: flex; align-items: center; justify-content: center; gap: 14px; width: 100%;
}
.vibehub-source .git-motion {
  flex: 0 0 auto; min-width: 72px;
  display: grid; grid-template-columns: 1fr auto; grid-template-areas: "label arrow" "term arrow";
  align-items: center; column-gap: 8px; text-align: right;
}
.vibehub-source .git-motion span { grid-area: label; color: var(--text-2); font-size: 11px; line-height: 1.3; white-space: nowrap; }
.vibehub-source .git-motion small { grid-area: term; color: var(--text-3); font: 600 10px/1.3 ui-monospace, SFMono-Regular, Menlo, monospace; }
.vibehub-source .git-motion i { grid-area: arrow; color: var(--git-blue); font-size: 18px; font-style: normal; }

.vibehub-source .git-file-card,.vibehub-source
.git-repo-card,.vibehub-source
.git-folder-card,.vibehub-source
.git-device-card,.vibehub-source
.git-version-card {
  flex: 1 1 0; min-width: 0; min-height: 72px;
  display: flex; align-items: center; gap: 10px; padding: 12px;
  border: 1px solid #dfe3e8; border-radius: 11px; background: var(--bg);
}
.vibehub-source .git-file-card > span:last-child,.vibehub-source
.git-repo-card > span:last-child,.vibehub-source
.git-folder-card > span:last-child,.vibehub-source
.git-device-card > span:last-child,.vibehub-source
.git-version-card > span:nth-child(2) { min-width: 0; display: grid; gap: 2px; }
.vibehub-source .git-file-card b,.vibehub-source
.git-repo-card b,.vibehub-source
.git-folder-card b,.vibehub-source
.git-device-card b,.vibehub-source
.git-version-card b { overflow: hidden; color: var(--git-ink); font-size: 12px; font-weight: 650; line-height: 1.35; text-overflow: ellipsis; white-space: nowrap; }
.vibehub-source .git-file-card small,.vibehub-source
.git-repo-card small,.vibehub-source
.git-folder-card small,.vibehub-source
.git-device-card small,.vibehub-source
.git-version-card small { color: var(--text-3); font-size: 10.5px; line-height: 1.4; }
.vibehub-source .git-file-card.is-change { border-color: #f0c36a; background: var(--warning-light); }
.vibehub-source .git-file-card.is-change small { color: var(--warning); }
.vibehub-source .git-file-mark {
  position: relative; flex: 0 0 auto; width: 28px; height: 34px;
  border: 1.5px solid #8c959f; border-radius: 5px; background: var(--bg);
}
.vibehub-source .git-file-mark::before { content: ""; position: absolute; left: 6px; right: 6px; top: 10px; height: 1.5px; background: #afb8c1; box-shadow: 0 6px 0 #d0d7de, 0 12px 0 #d0d7de; }
.vibehub-source .git-file-mark::after { content: ""; position: absolute; right: -1.5px; top: -1.5px; width: 8px; height: 8px; border-left: 1.5px solid #8c959f; border-bottom: 1.5px solid #8c959f; border-radius: 0 4px 0 3px; background: var(--bg-soft); }

.vibehub-source .git-version-card { position: relative; border-color: #dfe3e8; background: var(--bg); }
.vibehub-source .git-version-card.is-new { border-color: #d0d7de; background: var(--bg-soft); box-shadow: none; }
.vibehub-source .git-version-check {
  flex: 0 0 auto; width: 27px; height: 27px; display: grid; place-items: center;
  border-radius: 50%; color: var(--on-brand); background: var(--git-blue); font-size: 14px; font-weight: 700;
}
.vibehub-source .git-version-dots { flex: 0 0 auto; display: flex; align-items: center; gap: 0; }
.vibehub-source .git-version-dots i { position: relative; width: 17px; height: 2px; background: #b9c3cf; }
.vibehub-source .git-version-dots i::before { content: ""; position: absolute; left: -1px; top: 50%; width: 6px; height: 6px; border-radius: 50%; background: #8c959f; transform: translateY(-50%); }
.vibehub-source .git-version-dots i:last-child { width: 7px; }
.vibehub-source .git-version-dots i.is-current::before { width: 8px; height: 8px; background: var(--git-green); box-shadow: 0 0 0 3px var(--git-green-soft); }
.vibehub-source .git-story--git .git-version-card .git-version-dots,.vibehub-source
.git-story--commit .git-version-card .git-version-dots { display: none; }

.vibehub-source .git-history-preview { width: min(100%, 360px); display: grid; gap: 13px; }
.vibehub-source .git-history-preview > span { color: var(--text-2); font-size: 10.5px; font-weight: 650; }
.vibehub-source .git-history-preview > div { display: flex; align-items: center; padding-inline: 4px; }
.vibehub-source .git-history-preview > div i { flex: 0 0 auto; width: 11px; height: 11px; border: 3px solid #fff; border-radius: 50%; background: var(--git-blue); box-shadow: 0 0 0 2px var(--git-blue); }
.vibehub-source .git-history-preview > div i.is-current { width: 13px; height: 13px; background: var(--git-green); box-shadow: 0 0 0 2px var(--git-green), 0 0 0 6px var(--git-green-soft); }
.vibehub-source .git-history-preview > div b { flex: 1; height: 3px; background: linear-gradient(90deg, #89a3ed, #b8c5ea); }
.vibehub-source .git-history-preview > small { display: flex; justify-content: space-between; color: var(--text-3); font-size: 9.5px; }

.vibehub-source .git-repo-card.is-cloud { border-color: #c7d1df; background: var(--bg-soft); }
.vibehub-source .git-repo-card.is-success { border-color: #d0d7de; background: var(--bg-soft); }
.vibehub-source .git-repo-icon { flex: 0 0 auto; width: 34px; height: 29px; display: flex; align-items: flex-end; justify-content: center; gap: 3px; padding-bottom: 5px; border: 1.5px solid #57606a; border-radius: 8px; background: var(--bg); }
.vibehub-source .git-repo-icon i { width: 5px; height: 5px; border-radius: 50%; background: #57606a; }
.vibehub-source .git-repo-icon i:last-child { background: var(--git-green); }

.vibehub-source .git-device-card { background: var(--bg); }
.vibehub-source .git-device-screen { flex: 0 0 auto; width: 48px; height: 34px; display: grid; place-items: center; border: 1.5px solid #57606a; border-radius: 5px; background: var(--bg-soft); }
.vibehub-source .git-device-screen::after { content: ""; width: 24px; height: 3px; border-radius: 3px; background: #afb8c1; transform: translateY(14px); }
.vibehub-source .git-device-screen .git-version-dots { transform: translateY(3px); }
.vibehub-source .git-device-screen .git-version-dots i { width: 10px; }

.vibehub-source .git-folder-icon { position: relative; flex: 0 0 auto; width: 39px; height: 28px; border: 1.5px solid #6e7781; border-radius: 5px; background: var(--bg-soft); }
.vibehub-source .git-folder-icon::before { content: ""; position: absolute; left: 3px; top: -6px; width: 17px; height: 7px; border: 1.5px solid #6e7781; border-bottom: 0; border-radius: 4px 4px 0 0; background: var(--bg-soft); }
.vibehub-source .git-folder-card.is-green { border-color: #d0d7de; background: var(--bg-soft); }

/* Branch and merge keep Git's recognizable graph, but label it in plain Chinese. */
.vibehub-source .git-branch-visual { position: relative; width: min(100%, 510px); padding: 2px 6px 0 92px; }
.vibehub-source .git-branch-caption { position: absolute; left: 0; top: -1px; display: grid; gap: 1px; }
.vibehub-source .git-branch-caption.is-feature { top: 67px; }
.vibehub-source .git-branch-caption span { color: var(--git-blue); font-size: 11px; font-weight: 650; }
.vibehub-source .git-branch-caption.is-feature span { color: var(--git-green); }
.vibehub-source .git-branch-caption small { color: var(--text-3); font-size: 9.5px; }
.vibehub-source .git-branch-lane { height: 32px; display: flex; align-items: center; }
.vibehub-source .git-branch-lane i { position: relative; z-index: 1; flex: 0 0 auto; width: 10px; height: 10px; border: 2px solid #fff; border-radius: 50%; background: var(--git-blue); box-shadow: 0 0 0 2px var(--git-blue); }
.vibehub-source .git-branch-lane b { flex: 1 1 0; height: 3px; background: #94aaf1; }
.vibehub-source .git-branch-lane.is-feature { width: 62%; margin: 34px 0 0 38%; }
.vibehub-source .git-branch-lane.is-feature i { background: var(--git-green); box-shadow: 0 0 0 2px var(--git-green); }
.vibehub-source .git-branch-lane.is-feature b { background: #8bd2a7; }
.vibehub-source .git-branch-split { position: absolute; left: calc(38% + 92px); top: 28px; width: 30px; height: 38px; border-left: 3px solid #8bd2a7; border-bottom: 3px solid #8bd2a7; border-radius: 0 0 0 12px; }
.vibehub-source .git-branch-split span { position: absolute; left: 9px; top: 12px; width: max-content; color: #6e7781; font-size: 9.5px; }

.vibehub-source .git-merge-visual { position: relative; width: min(100%, 500px); min-height: 124px; padding-right: 190px; display: grid; align-content: center; gap: 28px; }
.vibehub-source .git-merge-source { display: grid; grid-template-columns: 56px 1fr; align-items: center; gap: 9px; }
.vibehub-source .git-merge-source span { color: var(--git-blue); font-size: 11px; font-weight: 650; }
.vibehub-source .git-merge-source.is-feature span { color: var(--git-green); }
.vibehub-source .git-merge-source > div { display: flex; align-items: center; }
.vibehub-source .git-merge-source i { flex: 0 0 auto; width: 9px; height: 9px; border-radius: 50%; background: var(--git-blue); }
.vibehub-source .git-merge-source b { flex: 1; height: 3px; background: #94aaf1; }
.vibehub-source .git-merge-source.is-feature i { background: var(--git-green); }
.vibehub-source .git-merge-source.is-feature b { background: #8bd2a7; }
.vibehub-source .git-merge-path { position: absolute; left: calc(100% - 192px); top: 39px; width: 55px; height: 49px; border: 3px solid var(--git-purple); border-left: 0; border-radius: 0 24px 24px 0; }
.vibehub-source .git-merge-path i { position: absolute; right: -6px; top: 18px; width: 10px; height: 10px; border: 2px solid #fff; border-radius: 50%; background: var(--git-purple); box-shadow: 0 0 0 3px #eadcfb; }
.vibehub-source .git-merge-result { position: absolute; right: 0; top: 35px; width: 170px; min-height: 70px; display: flex; align-items: center; gap: 9px; padding: 10px; border: 1px solid #cbb6ee; border-radius: 11px; background: var(--code-keyword-light); }
.vibehub-source .git-merge-result > span:last-child { display: grid; gap: 2px; }
.vibehub-source .git-merge-result b { font-size: 11.5px; }
.vibehub-source .git-merge-result small { color: var(--text-3); font-size: 9.5px; line-height: 1.35; }
.vibehub-source .git-merge-result .git-version-check { background: var(--git-purple); }

/* Remote: the local and cloud copies, with push and pull between them. */
.vibehub-source .git-remote-visual { width: min(100%, 560px); display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr); align-items: center; gap: 16px; }
.vibehub-source .git-remote-side { min-width: 0; }
.vibehub-source .git-remote-side .git-repo-card,.vibehub-source
.git-remote-side .git-device-card { min-height: 76px; }
.vibehub-source .git-remote-arrows { display: grid; gap: 8px; justify-items: center; }
.vibehub-source .git-remote-arrow { display: inline-flex; align-items: center; gap: 6px; padding: 5px 10px; border: 1px solid #c7d1df; border-radius: 999px; background: var(--bg-soft); color: var(--text-2); font-size: 10.5px; font-weight: 650; white-space: nowrap; }
.vibehub-source .git-remote-arrow.up { color: var(--git-blue); }
.vibehub-source .git-remote-arrow.down { color: var(--git-green); }
.vibehub-source .git-remote-anat { width: 100%; display: flex; justify-content: center; padding: 10px 12px; border: 1px solid var(--border); border-radius: 8px; background: var(--bg-soft); }
.vibehub-source .git-remote-url { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 12px; color: var(--text-2); overflow-wrap: anywhere; }

/* Review, worktree, stash, ignore and diff each explain one visible outcome. */
.vibehub-source .git-review-change,.vibehub-source
.git-review-checks { flex: 1 1 0; min-width: 0; min-height: 92px; display: grid; align-content: center; gap: 3px; padding: 12px; border: 1px solid #dfe3e8; border-radius: 11px; background: var(--bg); }
.vibehub-source .git-review-change > span { color: var(--git-green); font-size: 10px; font-weight: 650; }
.vibehub-source .git-review-change b { font-size: 12px; }
.vibehub-source .git-review-change small { color: var(--text-3); font-size: 10px; }
.vibehub-source .git-review-checks { border-color: #d0d7de; background: var(--bg-soft); }
.vibehub-source .git-review-checks span { color: var(--text-2); font-size: 10.5px; }
.vibehub-source .git-review-checks span i { color: var(--git-green); font-style: normal; font-weight: 700; }
.vibehub-source .git-review-checks b { margin-top: 3px; color: var(--green); font-size: 11px; }

.vibehub-source .git-worktree-visual { width: min(100%, 500px); margin: 0 auto; }
.vibehub-source .git-shared-history { width: max-content; max-width: 100%; margin: 0 auto; display: flex; align-items: center; gap: 12px; padding: 7px 12px; border: 1px solid #c7d1df; border-radius: 999px; background: var(--bg-soft); }
.vibehub-source .git-shared-history > span { color: var(--text-2); font-size: 10.5px; font-weight: 650; }
.vibehub-source .git-worktree-lines { width: 50%; height: 24px; margin: 0 auto; border-left: 1.5px solid #afb8c1; border-right: 1.5px solid #afb8c1; border-top: 1.5px solid #afb8c1; border-radius: 8px 8px 0 0; }
.vibehub-source .git-worktree-folders { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }

.vibehub-source .git-stash-visual { width: min(100%, 560px); display: grid; grid-template-columns: 1fr auto 130px; align-items: center; gap: 12px; }
.vibehub-source .git-drawer { position: relative; min-height: 78px; display: grid; align-content: center; gap: 2px; padding: 17px 12px 10px; border: 1px solid #b8a2df; border-radius: 7px 7px 11px 11px; background: var(--code-keyword-light); text-align: center; }
.vibehub-source .git-drawer-handle { position: absolute; left: 10px; right: 10px; top: 8px; height: 4px; border-radius: 4px; background: #b8a2df; }
.vibehub-source .git-drawer b { font-size: 11px; }
.vibehub-source .git-drawer small { color: var(--text-3); font-size: 9.5px; }
.vibehub-source .git-clean-state { grid-column: 1 / -1; justify-self: center; display: flex; align-items: center; gap: 8px; padding: 6px 10px; border-radius: 8px; background: var(--git-green-soft); }
.vibehub-source .git-clean-state > i { color: var(--git-green); font-style: normal; font-weight: 700; }
.vibehub-source .git-clean-state > span { display: flex; align-items: baseline; gap: 8px; }
.vibehub-source .git-clean-state b { color: var(--green); font-size: 10.5px; }
.vibehub-source .git-clean-state small { color: var(--text-2); font-size: 9.5px; }

.vibehub-source .git-ignore-visual { width: min(100%, 500px); display: grid; grid-template-columns: minmax(0, 1fr) minmax(150px, .8fr); gap: 14px; }
.vibehub-source .git-file-list { overflow: hidden; border: 1px solid #dfe3e8; border-radius: 10px; background: var(--bg); }
.vibehub-source .git-file-list > span { display: flex; align-items: center; gap: 7px; padding: 8px 10px; border-bottom: 1px solid #eef1f4; color: var(--text-2); font-size: 10.5px; }
.vibehub-source .git-file-list > span:last-child { border-bottom: 0; }
.vibehub-source .git-file-list > span i { width: 8px; height: 10px; border: 1px solid #8c959f; border-radius: 2px; }
.vibehub-source .git-file-list > span b { margin-left: auto; color: var(--git-green); font-size: 9.5px; font-weight: 650; }
.vibehub-source .git-file-list > span.is-secret { color: var(--warning); background: var(--warning-light); text-decoration: line-through; }
.vibehub-source .git-file-list > span.is-secret b { color: var(--red); text-decoration: none; }
.vibehub-source .git-ignore-rule { display: flex; align-items: center; gap: 9px; padding: 12px; border: 1px solid #d0d7de; border-radius: 10px; background: var(--bg-soft); }
.vibehub-source .git-shield { flex: 0 0 auto; width: 30px; height: 34px; display: grid; place-items: center; border-radius: 8px 8px 13px 13px; color: var(--on-status); background: var(--git-green); font-size: 17px; font-weight: 650; }
.vibehub-source .git-ignore-rule > span:last-child { display: grid; gap: 2px; }
.vibehub-source .git-ignore-rule b { font: 650 11px/1.3 ui-monospace, Menlo, monospace; }
.vibehub-source .git-ignore-rule small { color: var(--text-2); font-size: 9.5px; line-height: 1.4; }

.vibehub-source .git-diff-visual { width: min(100%, 500px); display: flex; align-items: center; gap: 12px; }
.vibehub-source .git-diff-card { flex: 1 1 0; min-width: 0; min-height: 96px; display: grid; align-content: center; gap: 5px; padding: 12px; border: 1px solid #dfe3e8; border-radius: 11px; background: var(--bg); }
.vibehub-source .git-diff-card > span { color: var(--text-2); font-size: 10px; font-weight: 650; }
