.vibehub-source .git-diff-card b { display: flex; align-items: center; gap: 7px; padding: 6px 8px; border-radius: 6px; font-size: 11px; font-weight: 600; }
.vibehub-source .git-diff-card b i { font-style: normal; font-size: 13px; }
.vibehub-source .git-diff-card.is-before { border-color: #d0d7de; background: var(--bg); }
.vibehub-source .git-diff-card.is-before b { color: var(--red); background: var(--red-light); }
.vibehub-source .git-diff-card.is-after { border-color: #d0d7de; background: var(--bg); }
