  background: var(--bg);
}
.vibehub-source .td-browser-bar {
  display: grid;
  grid-template-columns: 10px 10px 10px minmax(0, 1fr) auto;
  align-items: center;
  gap: 7px;
  min-height: 44px;
  padding: 8px 14px;
  border-bottom: 1px solid var(--td-line);
  background: var(--td-faint);
}
.vibehub-source .td-browser-bar > i { width: 9px; height: 9px; border-radius: 50%; background: var(--bg-hover); }
.vibehub-source .td-browser-bar code { margin-left: 6px; padding: 5px 10px; border-radius: 6px; color: var(--td-muted); background: var(--bg); font: 14px/1.3 ui-monospace, SFMono-Regular, Menlo, monospace; }
.vibehub-source .td-browser-bar b { padding: 4px 8px; border-radius: 5px; color: var(--td-ink); background: var(--bg-hover); font-size: 13px; }
.vibehub-source .td-tick { display: flex; align-items: flex-start; gap: 9px; color: var(--td-muted); font-size: 15px; line-height: 1.5; }
.vibehub-source .td-tick i { display: grid; place-items: center; flex: 0 0 20px; height: 20px; margin-top: 1px; border-radius: 50%; color: var(--text-2); background: var(--bg-hover); font: 700 13px/1 sans-serif; }
.vibehub-source .td-tick.is-pass { color: var(--td-ink); }
