.vibehub-source .td-itinerary { padding: 28px 32px; }
.vibehub-source .td-itinerary-title { display: flex; justify-content: space-between; gap: 20px; margin-bottom: 26px; }
.vibehub-source .td-itinerary-title span { font-size: 21px; font-weight: 750; }
.vibehub-source .td-itinerary-title b { font-size: 18px; }
.vibehub-source .td-trip-line { display: grid; grid-template-columns: 48px 16px minmax(0, 1fr); gap: 10px; min-height: 72px; }
.vibehub-source .td-trip-line time { color: var(--td-muted); font: 14px/1.4 ui-monospace, monospace; }
