.vibehub-source .td-workbench > header span,.vibehub-source  .td-data-console > header span,.vibehub-source  .td-flow-map > header span,.vibehub-source  .td-observability > header span { color: var(--td-muted); font-size: 14px; }
.vibehub-source .td-editor-layout { display: grid; grid-template-columns: 150px minmax(0, 1fr); min-height: 230px; }
